def linear_search(values, target):
    for index, value in enumerate(values):
        if value == target:
            return index
    return -1

numbers = [4, 8, 15, 16, 23, 42]
print(linear_search(numbers, 42))

def binary_search(values, target):
    left = 0
    right = len(values) - 1

    while left <= right:
        middle = (left + right) // 2

        if values[middle] == target:
            return middle
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle - 1

    return -1

numbers = [2, 5, 9, 13, 21, 34, 55, 89]
print(binary_search(numbers, 34))

